-- Report ID : RPT_406
-- Report    : Items Not Ordered 30 Days 406
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      im.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.PACK_IND                                           AS pack_ind,     im.STATUS                                             AS item_status,      ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS item_loc_status_desc,      ril.PRIMARY_REPL_SUPPLIER                             AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     isc.LEAD_TIME                                         AS lead_time,     isc.PICKUP_LEAD_TIME                                  AS pickup_lead_time,     isc.UNIT_COST                                         AS unit_cost,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'     END                                                   AS order_control_desc,     ril.MIN_STOCK                                         AS min_stock,     ril.MAX_STOCK                                         AS max_stock,     ril.REVIEW_CYCLE                                      AS review_cycle,     ril.SOURCE_WH                                         AS source_warehouse,     ril.NON_SCALING_IND                                   AS scaling_exempt_ind,      last_ord.LAST_ORDER_DATE                              AS last_po_written_date,     last_ord.LAST_ORDER_NO                                AS last_po_number,     last_ord.LAST_ORDER_STATUS                            AS last_po_status,     last_ord.LAST_NOT_AFTER_DATE                          AS last_po_not_after_date,      CASE         WHEN last_ord.LAST_ORDER_DATE IS NULL         THEN NULL         ELSE TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE)     END                                                   AS days_since_last_order,      CASE         WHEN last_ord.LAST_ORDER_DATE IS NULL         THEN 'NEVER ORDERED'         WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) BETWEEN 30 AND 45         THEN '30 - 45 Days'         WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) BETWEEN 46 AND 60         THEN '46 - 60 Days'         WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) BETWEEN 61 AND 90         THEN '61 - 90 Days'         WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) > 90         THEN '90+ Days'         ELSE 'WITHIN 30 DAYS'     END                                                   AS no_order_aging_bucket,      ils.STOCK_ON_HAND                                     AS current_soh,     ils.AV_COST                                           AS weighted_avg_cost,      il.SELLING_UNIT_RETAIL                                AS unit_retail,     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)                                                           AS soh_cost_value,      CASE         WHEN NVL(ils.STOCK_ON_HAND, 0) = 0         THEN 'OUT OF STOCK'         WHEN NVL(ils.STOCK_ON_HAND, 0) < NVL(ril.MIN_STOCK, 0)         THEN 'BELOW MIN'         WHEN NVL(ils.STOCK_ON_HAND, 0) BETWEEN              NVL(ril.MIN_STOCK, 0) AND NVL(ril.MAX_STOCK, 0)         THEN 'WITHIN RANGE'         WHEN NVL(ils.STOCK_ON_HAND, 0) > NVL(ril.MAX_STOCK, 0)         THEN 'ABOVE MAX'         ELSE 'UNKNOWN'     END                                                   AS stock_position,      open_ord.OPEN_ORDER_COUNT                             AS open_order_count,     open_ord.OPEN_ORDER_QTY                               AS open_order_qty,      CASE         WHEN NVL(ils.STOCK_ON_HAND, 0) = 0              AND last_ord.LAST_ORDER_DATE IS NULL         THEN 'CRITICAL - OOS and Never Ordered'         WHEN NVL(ils.STOCK_ON_HAND, 0) = 0              AND TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) > 30         THEN 'CRITICAL - OOS, No Order in 30+ Days'         WHEN NVL(ils.STOCK_ON_HAND, 0) < NVL(ril.MIN_STOCK, 0)         THEN 'HIGH - Below Min, No Order in 30+ Days'         WHEN last_ord.LAST_ORDER_DATE IS NULL         THEN 'HIGH - Never Ordered, Repl Active'         WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) > 90         THEN 'MEDIUM - No Order in 90+ Days'         ELSE 'LOW - Monitor'     END                                                   AS urgency_flag,      CASE         WHEN ril.REPL_ORDER_CTRL = 'M'         THEN 'Manual order control - buyer action required to raise PO'         WHEN ril.REPL_ORDER_CTRL = 'B'         THEN 'Buyer worksheet - buyer must approve generated worksheet'         WHEN ril.REPL_ORDER_CTRL = 'A'              AND last_ord.LAST_ORDER_DATE IS NULL         THEN 'Auto order - check rplbld.pc batch and supplier setup'         WHEN sp.SUP_STATUS != 'A'         THEN 'Supplier inactive - reactivate or assign alternate supplier'         WHEN NVL(isc.PICKUP_LEAD_TIME, 0) = 0              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'Pickup lead time missing - correct to allow repl order generation'         ELSE 'Review replenishment setup and last batch run log'     END                                                   AS recommended_action,      ril.LAST_UPDATE_DATETIME                              AS last_repl_update  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM          = il.ITEM                                                      AND  ril.LOCATION      = il.LOC                                                      AND  ril.LOC_TYPE      = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM          = im.ITEM                                                      AND  im.TRAN_LEVEL     = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT           = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT           = c.DEPT                                                      AND  im.CLASS          = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT           = sc.DEPT                                                      AND  im.CLASS          = sc.CLASS                                                      AND  im.SUBCLASS       = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION      = st.STORE                                                      AND  il.LOC_TYPE       = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION      = wh.WH                                                      AND  il.LOC_TYPE       = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM          = ils.ITEM                                                      AND  ril.LOCATION      = ils.LOC                                                      AND  ils.LOC_TYPE      = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM          = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN (         SELECT             ol.ITEM,             ol.LOCATION,             ol.LOC_TYPE,             MAX(oh.WRITTEN_DATE)                          AS last_order_date,             MAX(oh.ORDER_NO)                 KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)                                                           AS last_order_no,             MAX(oh.STATUS)                 KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)                                                           AS last_order_status,             MAX(oh.NOT_AFTER_DATE)                 KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)                                                           AS last_not_after_date         FROM  MFCS_RDS.RDS_WV_ORDLOC              ol         JOIN  MFCS_RDS.RDS_WV_ORDHEAD             oh   ON  ol.ORDER_NO    = oh.ORDER_NO         WHERE oh.STATUS IN ('W','S','A','C')         GROUP BY ol.ITEM, ol.LOCATION, ol.LOC_TYPE     ) last_ord                                            ON  ril.ITEM      = last_ord.ITEM                                                          AND  ril.LOCATION  = last_ord.LOCATION                                                          AND  ril.LOC_TYPE  = last_ord.LOC_TYPE      LEFT JOIN (         SELECT             ol.ITEM,             ol.LOCATION,             COUNT(DISTINCT oh.ORDER_NO)                   AS open_order_count,             SUM(ol.QTY_ORDERED - NVL(ol.QTY_RECEIVED, 0)) AS open_order_qty         FROM  MFCS_RDS.RDS_WV_ORDLOC              ol         JOIN  MFCS_RDS.RDS_WV_ORDHEAD             oh   ON  ol.ORDER_NO    = oh.ORDER_NO         WHERE oh.STATUS IN ('W','S','A')         GROUP BY ol.ITEM, ol.LOCATION     ) open_ord                                            ON  ril.ITEM      = open_ord.ITEM                                                          AND  ril.LOCATION  = open_ord.LOCATION  WHERE     ril.REPL_METHOD     IS NOT NULL     AND il.STATUS       IN ('A','C')     AND im.STATUS        = 'A'     AND (         last_ord.LAST_ORDER_DATE IS NULL         OR TRUNC(last_ord.LAST_ORDER_DATE) < TRUNC(SYSDATE) - 30     )  ORDER BY     CASE         WHEN NVL(ils.STOCK_ON_HAND,0) = 0 AND last_ord.LAST_ORDER_DATE IS NULL         THEN 'CRITICAL - OOS and Never Ordered'         WHEN NVL(ils.STOCK_ON_HAND,0) = 0              AND TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) > 30         THEN 'CRITICAL - OOS, No Order in 30+ Days'         WHEN NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)         THEN 'HIGH - Below Min, No Order in 30+ Days'         WHEN last_ord.LAST_ORDER_DATE IS NULL         THEN 'HIGH - Never Ordered, Repl Active'         WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) > 90         THEN 'MEDIUM - No Order in 90+ Days'         ELSE 'LOW - Monitor'     END,     (TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE)) DESC NULLS FIRST,     d.DEPT_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END